#!/usr/bin/env python3
"""
Export rust-analyzer document symbols for rust-lang/rust as JSONL.

This uses the same LSP backend configured for Kiro in:
  /home/jeremy/git/repos/rust-lang/rust/.kiro/settings/lsp.json

Output records are one symbol per line:
  {"file_path": "...", "name": "...", "kind": 12, "line_start": 1, ...}
"""

from __future__ import annotations

import argparse
import json
import os
import queue
import subprocess
import sys
import threading
import time
from pathlib import Path
from typing import Any


GIT_ROOT = Path("/home/jeremy/git")
REPO_ROOT = GIT_ROOT / "repos" / "rust-lang" / "rust"
DEFAULT_OUT = GIT_ROOT / "lsp" / "rust-lang-rust-symbols.jsonl"
KIRO_LSP_CONFIG = REPO_ROOT / ".kiro" / "settings" / "lsp.json"


def uri_for(path: Path) -> str:
    return path.resolve().as_uri()


def git_files(repo_root: Path, limit: int | None = None) -> list[str]:
    files = subprocess.check_output(["git", "ls-files", "*.rs"], cwd=repo_root, text=True).splitlines()
    return files[:limit] if limit else files


class LspClient:
    def __init__(self, command: list[str], cwd: Path):
        self.proc = subprocess.Popen(
            command,
            cwd=cwd,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=False,
        )
        self.next_id = 1
        self.responses: dict[int, Any] = {}
        self.notifications: queue.Queue[Any] = queue.Queue()
        self._lock = threading.Lock()
        self._reader = threading.Thread(target=self._read_loop, daemon=True)
        self._reader.start()
        self._stderr = threading.Thread(target=self._stderr_loop, daemon=True)
        self._stderr.start()

    def _stderr_loop(self) -> None:
        assert self.proc.stderr is not None
        for raw in self.proc.stderr:
            line = raw.decode("utf-8", errors="replace").rstrip()
            if line:
                print(f"rust-analyzer: {line}", file=sys.stderr)

    def _read_loop(self) -> None:
        assert self.proc.stdout is not None
        while True:
            headers: dict[str, str] = {}
            while True:
                line = self.proc.stdout.readline()
                if not line:
                    return
                if line in (b"\r\n", b"\n"):
                    break
                key, value = line.decode("ascii", errors="replace").split(":", 1)
                headers[key.lower()] = value.strip()
            length = int(headers.get("content-length", "0"))
            if length <= 0:
                continue
            body = self.proc.stdout.read(length)
            msg = json.loads(body.decode("utf-8"))
            if "id" in msg:
                with self._lock:
                    self.responses[msg["id"]] = msg
            else:
                self.notifications.put(msg)

    def send(self, payload: dict[str, Any]) -> None:
        assert self.proc.stdin is not None
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        header = f"Content-Length: {len(body)}\r\n\r\n".encode("ascii")
        self.proc.stdin.write(header + body)
        self.proc.stdin.flush()

    def request(self, method: str, params: dict[str, Any], timeout: float = 120.0) -> Any:
        req_id = self.next_id
        self.next_id += 1
        self.send({"jsonrpc": "2.0", "id": req_id, "method": method, "params": params})
        deadline = time.time() + timeout
        while time.time() < deadline:
            with self._lock:
                msg = self.responses.pop(req_id, None)
            if msg is not None:
                if "error" in msg:
                    raise RuntimeError(f"{method} failed: {msg['error']}")
                return msg.get("result")
            if self.proc.poll() is not None:
                raise RuntimeError(f"LSP process exited with {self.proc.returncode}")
            time.sleep(0.05)
        raise TimeoutError(f"{method} timed out")

    def notify(self, method: str, params: dict[str, Any]) -> None:
        self.send({"jsonrpc": "2.0", "method": method, "params": params})

    def close(self) -> None:
        try:
            self.request("shutdown", {}, timeout=10)
            self.notify("exit", {})
        finally:
            try:
                self.proc.terminate()
            except ProcessLookupError:
                pass


def flatten_symbols(symbols: list[dict[str, Any]], rel_path: str) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []

    def walk(items: list[dict[str, Any]], parent: str = "") -> None:
        for item in items:
            name = item.get("name", "")
            qualified = f"{parent}::{name}" if parent and name else name
            rng = item.get("selectionRange") or item.get("range") or {}
            start = rng.get("start", {})
            end = rng.get("end", {})
            if name and start and end:
                out.append({
                    "file_path": rel_path,
                    "name": name,
                    "qualified_name": qualified,
                    "kind": item.get("kind"),
                    "line_start": int(start.get("line", 0)) + 1,
                    "line_end": int(end.get("line", 0)) + 1,
                    "character_start": int(start.get("character", 0)),
                    "character_end": int(end.get("character", 0)),
                })
            children = item.get("children") or []
            if children:
                walk(children, qualified)

    walk(symbols)
    return out


def load_command() -> list[str]:
    if KIRO_LSP_CONFIG.exists():
        data = json.loads(KIRO_LSP_CONFIG.read_text(encoding="utf-8"))
        rust = data.get("languages", {}).get("rust", {})
        command = rust.get("command") or "rust-analyzer"
        args = rust.get("args") or []
        return [command, *args]
    return ["rust-analyzer"]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--out", type=Path, default=DEFAULT_OUT)
    parser.add_argument("--limit", type=int, default=0, help="Limit files for testing.")
    parser.add_argument("--timeout", type=float, default=180.0)
    args = parser.parse_args()

    files = git_files(REPO_ROOT, args.limit or None)
    args.out.parent.mkdir(parents=True, exist_ok=True)

    client = LspClient(load_command(), REPO_ROOT)
    try:
        client.request("initialize", {
            "processId": os.getpid(),
            "rootUri": uri_for(REPO_ROOT),
            "workspaceFolders": [{"uri": uri_for(REPO_ROOT), "name": "rust"}],
            "capabilities": {
                "textDocument": {
                    "documentSymbol": {
                        "hierarchicalDocumentSymbolSupport": True,
                    }
                }
            },
        }, timeout=args.timeout)
        client.notify("initialized", {})

        count = 0
        with args.out.open("w", encoding="utf-8") as f:
            for idx, rel_path in enumerate(files, 1):
                abs_path = REPO_ROOT / rel_path
                text = abs_path.read_text(encoding="utf-8", errors="replace")
                uri = uri_for(abs_path)
                client.notify("textDocument/didOpen", {
                    "textDocument": {
                        "uri": uri,
                        "languageId": "rust",
                        "version": 1,
                        "text": text,
                    }
                })
                try:
                    symbols = client.request(
                        "textDocument/documentSymbol",
                        {"textDocument": {"uri": uri}},
                        timeout=args.timeout,
                    ) or []
                    for record in flatten_symbols(symbols, rel_path):
                        f.write(json.dumps(record, separators=(",", ":")) + "\n")
                        count += 1
                finally:
                    client.notify("textDocument/didClose", {"textDocument": {"uri": uri}})
                if idx % 250 == 0:
                    print(f"processed {idx}/{len(files)} files, {count} symbols", file=sys.stderr)
        print(f"wrote {count} symbols to {args.out}")
        return 0
    finally:
        client.close()


if __name__ == "__main__":
    raise SystemExit(main())

