#!/usr/bin/env python3
from __future__ import annotations

import argparse
import hashlib
import json
import logging
import os
import re
import subprocess
import sys
import time
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable, Iterator


ROOT = Path("/home/jeremy/git")
REPOS = ROOT / "repos"
STATE_DIR = ROOT / "logs" / "vector-state"
DEFAULT_MODEL = "voyage-4-lite"
DEFAULT_DIMENSION = 1024
DEFAULT_BATCH_SIZE = 24
DEFAULT_CHUNK_CHARS = 12_000
DEFAULT_OVERLAP_CHARS = 800
DEFAULT_MAX_FILE_BYTES = 1_500_000

INCLUDE_EXTS = {
    ".rs", ".go", ".py", ".ts", ".tsx", ".js", ".jsx", ".java",
    ".c", ".h", ".cc", ".cpp", ".cxx", ".hpp", ".hh",
    ".proto", ".toml", ".json", ".yaml", ".yml", ".md", ".rst",
    ".txt", ".sh", ".sql", ".rego", ".cue", ".xml",
}

SKIP_PARTS = {
    ".git", "target", "node_modules", "dist", "build", ".venv",
    "__pycache__", ".mypy_cache", ".pytest_cache", ".gradle", ".idea",
}


@dataclass(frozen=True)
class Chunk:
    repo: str
    rel_path: str
    abs_path: Path
    text: str
    chunk_index: int
    line_start: int
    line_end: int
    char_start: int
    char_end: int
    file_sha256: str
    language: str


def run_git(repo_root: Path, args: list[str]) -> str:
    return subprocess.check_output(["git", *args], cwd=repo_root, text=True).strip()


def git_files(repo_root: Path) -> list[str]:
    try:
        return run_git(repo_root, ["ls-files"]).splitlines()
    except Exception:
        return [
            str(path.relative_to(repo_root))
            for path in repo_root.rglob("*")
            if path.is_file() and ".git" not in path.parts
        ]


def git_meta(repo_root: Path) -> dict[str, str]:
    def maybe(args: list[str]) -> str:
        try:
            return run_git(repo_root, args)
        except Exception:
            return ""
    return {
        "commit": maybe(["rev-parse", "HEAD"]),
        "branch": maybe(["branch", "--show-current"]),
        "remote": maybe(["config", "--get", "remote.origin.url"]),
    }


def language_for(path: str) -> str:
    ext = Path(path).suffix.lower()
    return {
        ".go": "go", ".py": "python", ".ts": "typescript", ".tsx": "typescript",
        ".js": "javascript", ".jsx": "javascript", ".java": "java", ".c": "c",
        ".h": "c-header", ".cc": "cpp", ".cpp": "cpp", ".cxx": "cpp",
        ".hpp": "cpp-header", ".hh": "cpp-header", ".proto": "protobuf",
        ".md": "markdown", ".yaml": "yaml", ".yml": "yaml", ".json": "json",
        ".toml": "toml", ".sh": "shell", ".rego": "rego", ".cue": "cue",
        ".xml": "xml", ".rs": "rust",
    }.get(ext, ext.lstrip(".") or "text")


def slug(value: str) -> str:
    value = re.sub(r"[^a-zA-Z0-9]+", "-", value).strip("-").lower()
    return value or "root"


def should_skip(rel_path: str) -> bool:
    path = Path(rel_path)
    if any(part in SKIP_PARTS for part in path.parts):
        return True
    return path.suffix.lower() not in INCLUDE_EXTS


def line_number_at(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def chunk_text(text: str, chunk_chars: int, overlap_chars: int) -> Iterator[tuple[str, int, int]]:
    if len(text) <= chunk_chars:
        yield text, 0, len(text)
        return
    start = 0
    while start < len(text):
        hard_end = min(start + chunk_chars, len(text))
        end = hard_end
        if hard_end < len(text):
            split = text.rfind("\n\n", start + chunk_chars // 2, hard_end)
            if split == -1:
                split = text.rfind("\n", start + chunk_chars // 2, hard_end)
            if split != -1:
                end = split + 1
        piece = text[start:end].strip()
        if piece:
            yield piece, start, end
        if end >= len(text):
            break
        start = max(0, end - overlap_chars)


def iter_chunks(repo: str, repo_root: Path, args: argparse.Namespace) -> Iterator[Chunk]:
    for rel_path in git_files(repo_root):
        if should_skip(rel_path):
            continue
        abs_path = repo_root / rel_path
        try:
            if abs_path.stat().st_size > args.max_file_bytes:
                continue
            text = abs_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if not text.strip():
            continue
        sha = hashlib.sha256(text.encode("utf-8", errors="replace")).hexdigest()
        for idx, (chunk, start, end) in enumerate(chunk_text(text, args.chunk_chars, args.overlap_chars)):
            yield Chunk(
                repo=repo,
                rel_path=rel_path,
                abs_path=abs_path,
                text=chunk,
                chunk_index=idx,
                line_start=line_number_at(text, start),
                line_end=line_number_at(text, end),
                char_start=start,
                char_end=end,
                file_sha256=sha,
                language=language_for(rel_path),
            )


def point_id(group: str, chunk: Chunk, commit: str) -> str:
    stable = f"{group}:{chunk.repo}:{commit}:{chunk.rel_path}:{chunk.chunk_index}:{chunk.line_start}:{chunk.line_end}"
    return str(uuid.uuid5(uuid.NAMESPACE_URL, stable))


def payload(group: str, chunk: Chunk, meta: dict[str, str]) -> dict:
    source_url = ""
    if meta.get("remote", "").startswith("https://github.com/") and meta.get("commit"):
        base = meta["remote"].removesuffix(".git")
        source_url = f"{base}/blob/{meta['commit']}/{chunk.rel_path}#L{chunk.line_start}-L{chunk.line_end}"
    subid = f"obs.software.{slug(group)}-{slug(chunk.repo)}-{slug(chunk.rel_path)}.index.chunk-{chunk.chunk_index:04d}@v1"
    return {
        "text": chunk.text,
        "uuid": point_id(group, chunk, meta.get("commit", "")),
        "subid": subid,
        "repo_group": group,
        "repo": chunk.repo,
        "remote": meta.get("remote", ""),
        "branch": meta.get("branch", ""),
        "commit": meta.get("commit", ""),
        "file_path": chunk.rel_path,
        "file_name": Path(chunk.rel_path).name,
        "extension": Path(chunk.rel_path).suffix.lower(),
        "language": chunk.language,
        "chunk_index": chunk.chunk_index,
        "line_start": chunk.line_start,
        "line_end": chunk.line_end,
        "char_start": chunk.char_start,
        "char_end": chunk.char_end,
        "file_sha256": chunk.file_sha256,
        "source_url": source_url,
        "category": "obs",
        "component_type": "software",
        "subject": slug(f"{group}-{chunk.repo}-{chunk.rel_path}"),
        "verb": "index",
        "facet": f"chunk-{chunk.chunk_index:04d}",
        "version": 1,
        "control_refs": [],
        "statement_refs": [],
        "kiro_lsp": {
            "state_dir": str(ROOT / "logs" / "kiro-lsp-state"),
            "expected_done_file": f"{group}.{chunk.repo.replace('/', '__')}.done",
        },
        "mouseover": {
            "title": f"{chunk.repo}:{chunk.rel_path}:{chunk.line_start}",
            "subtitle": chunk.language,
            "detail": next((line.strip()[:220] for line in chunk.text.splitlines() if line.strip()), ""),
            "source_range": f"{chunk.rel_path}:{chunk.line_start}-{chunk.line_end}",
            "subid": subid,
        },
    }


def estimate_tokens(text: str) -> int:
    return max(1, len(text) // 4)


def batched(items: Iterable[Chunk], size: int) -> Iterator[list[Chunk]]:
    batch: list[Chunk] = []
    for item in items:
        batch.append(item)
        if len(batch) >= size:
            yield batch
            batch = []
    if batch:
        yield batch


def is_rate_limit(exc: Exception) -> bool:
    msg = str(exc).lower()
    return "rate limit" in msg or "too many requests" in msg or "429" in msg


def is_batch_too_large(exc: Exception) -> bool:
    msg = str(exc).lower()
    return "max allowed tokens" in msg or "lower the number of tokens" in msg


def import_clients():
    try:
        import voyageai
        from qdrant_client import QdrantClient
        from qdrant_client.models import Distance, PointStruct, VectorParams
    except ImportError as exc:
        raise SystemExit(f"Missing dependency: {exc}") from exc
    return voyageai, QdrantClient, Distance, PointStruct, VectorParams


def ensure_collection(client, collection: str, dimension: int, Distance, VectorParams) -> None:
    if not client.collection_exists(collection):
        client.create_collection(
            collection_name=collection,
            vectors_config=VectorParams(size=dimension, distance=Distance.COSINE),
        )
    for field in ["uuid", "subid", "repo_group", "repo", "language", "file_path", "category", "component_type"]:
        try:
            client.create_payload_index(collection, field_name=field, field_schema="keyword")
        except Exception:
            pass


def read_repos(list_file: Path) -> list[str]:
    return [
        line.strip()
        for line in list_file.read_text(encoding="utf-8").splitlines()
        if line.strip() and not line.strip().startswith("#")
    ]


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--group", required=True)
    parser.add_argument("--list-file", type=Path, required=True)
    parser.add_argument("--collection", required=True)
    parser.add_argument("--model", default=DEFAULT_MODEL)
    parser.add_argument("--dimension", type=int, default=DEFAULT_DIMENSION)
    parser.add_argument("--batch-size", type=int, default=DEFAULT_BATCH_SIZE)
    parser.add_argument("--chunk-chars", type=int, default=DEFAULT_CHUNK_CHARS)
    parser.add_argument("--overlap-chars", type=int, default=DEFAULT_OVERLAP_CHARS)
    parser.add_argument("--max-file-bytes", type=int, default=DEFAULT_MAX_FILE_BYTES)
    parser.add_argument("--qdrant-url", default="http://localhost:6333")
    args = parser.parse_args()

    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
    if not os.environ.get("VOYAGE_API_KEY"):
        raise SystemExit("VOYAGE_API_KEY missing")

    STATE_DIR.mkdir(parents=True, exist_ok=True)
    voyageai, QdrantClient, Distance, PointStruct, VectorParams = import_clients()
    voyage = voyageai.Client()
    qdrant = QdrantClient(url=args.qdrant_url)
    ensure_collection(qdrant, args.collection, args.dimension, Distance, VectorParams)

    def upsert_batch(batch: list[Chunk], meta_by_repo: dict[str, dict[str, str]], depth: int = 0) -> int:
        try:
            result = voyage.embed(
                [c.text for c in batch],
                model=args.model,
                input_type="document",
                output_dimension=args.dimension,
            )
        except Exception as exc:
            if is_batch_too_large(exc) and len(batch) > 1:
                mid = len(batch) // 2
                logging.warning("splitting oversized batch size=%s: %s", len(batch), exc)
                return upsert_batch(batch[:mid], meta_by_repo, depth + 1) + upsert_batch(batch[mid:], meta_by_repo, depth + 1)
            if is_rate_limit(exc):
                sleep_s = min(1800, 60 * (2 ** min(depth, 5)))
                logging.warning("rate limited; sleeping %ss: %s", sleep_s, exc)
                time.sleep(sleep_s)
                return upsert_batch(batch, meta_by_repo, depth + 1)
            raise
        points = []
        for chunk, vector in zip(batch, result.embeddings):
            meta = meta_by_repo[chunk.repo]
            points.append(PointStruct(
                id=point_id(args.group, chunk, meta.get("commit", "")),
                vector=vector,
                payload=payload(args.group, chunk, meta),
            ))
        qdrant.upsert(collection_name=args.collection, points=points, wait=False)
        return len(points)

    total = 0
    for repo in read_repos(args.list_file):
        repo_root = REPOS / repo
        if not repo_root.is_dir():
            logging.warning("missing repo: %s", repo)
            continue
        done = STATE_DIR / f"{args.group}.{repo.replace('/', '__')}.done"
        if done.exists():
            logging.info("skip done repo=%s", repo)
            continue
        meta = git_meta(repo_root)
        meta_by_repo = {repo: meta}
        repo_total = 0
        for batch in batched(iter_chunks(repo, repo_root, args), args.batch_size):
            repo_total += upsert_batch(batch, meta_by_repo)
            total += len(batch)
            if repo_total % (args.batch_size * 10) == 0:
                logging.info("group=%s repo=%s upserted=%s total=%s", args.group, repo, repo_total, total)
        done.write_text(json.dumps({"repo": repo, "chunks": repo_total, "finished_at": time.time()}) + "\n")
        logging.info("done group=%s repo=%s chunks=%s", args.group, repo, repo_total)
    logging.info("complete group=%s total=%s", args.group, total)
    return 0


if __name__ == "__main__":
    sys.exit(main())

