import os, requests
from pathlib import Path

# Load simple KEY=value lines without printing values.
for line in Path('/home/jeremy/.bash_secrets').read_text().splitlines():
    line=line.strip()
    if not line or line.startswith('#') or '=' not in line:
        continue
    k,v=line.split('=',1)
    if k in ('VOYAGE_API_KEY','VOYAGE_API_KEY_RUST'):
        os.environ[k]=v.strip().strip('"').strip("'")

def endpoint_for(key):
    return 'https://ai.mongodb.com/v1/embeddings' if key.startswith('al-') else 'https://api.voyageai.com/v1/embeddings'

def probe(name, model):
    key=os.environ.get(name)
    if not key:
        print(name, model, 'missing')
        return
    try:
        r=requests.post(endpoint_for(key), headers={'Authorization': f'Bearer {key}', 'Content-Type': 'application/json'}, json={'model': model, 'input': ['ping'], 'input_type': 'query'}, timeout=20)
        print(name, key[:3], model, r.status_code, (r.text[:120].replace('\n',' ') if r.status_code != 200 else 'ok'))
    except Exception as e:
        print(name, key[:3], model, 'ERR', type(e).__name__, str(e)[:120])

for name in ('VOYAGE_API_KEY','VOYAGE_API_KEY_RUST'):
    for model in ('voyage-code-3','voyage-4-lite'):
        probe(name, model)
