from pathlib import Path
p = Path('/home/jeremy/.bash_secrets')
text = p.read_text()
lines = text.splitlines()
vals = {}
for line in lines:
    stripped = line.strip()
    if not stripped or stripped.startswith('#') or '=' not in stripped:
        continue
    k, v = stripped.split('=', 1)
    if k in {'VOYAGE_API_KEY', 'VOYAGE_API_KEY_RUST', 'VOYAGE_API_KEY_LITE'}:
        vals[k] = v
if 'VOYAGE_API_KEY' not in vals or 'VOYAGE_API_KEY_RUST' not in vals:
    raise SystemExit('missing VOYAGE_API_KEY or VOYAGE_API_KEY_RUST')
old_general = vals['VOYAGE_API_KEY']
old_rust = vals['VOYAGE_API_KEY_RUST']
seen_lite = False
out = []
for line in lines:
    stripped = line.strip()
    if stripped.startswith('VOYAGE_API_KEY_RUST='):
        out.append(f'VOYAGE_API_KEY_RUST={old_general}')
    elif stripped.startswith('VOYAGE_API_KEY_LITE='):
        out.append(f'VOYAGE_API_KEY_LITE={old_rust}')
        seen_lite = True
    else:
        out.append(line)
if not seen_lite:
    insert_at = len(out)
    for i, line in enumerate(out):
        if line.strip().startswith('VOYAGE_API_KEY_RUST='):
            insert_at = i + 1
            break
    out.insert(insert_at, f'VOYAGE_API_KEY_LITE={old_rust}')
backup = p.with_suffix(p.suffix + '.bak-voyage-swap')
backup.write_text(text)
p.write_text('\n'.join(out) + ('\n' if text.endswith('\n') else ''))
PY
